#define RATIO iResolution.x/iResolution.y
#define COUNT 4
#define XALIGNED false
#define PI 3.141592
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = fragCoord/iResolution.xy-.5;
    uv.x *= RATIO;

    float m = 1.;  // magnitude, i.e. gravitation strength
    vec2 circs[4];

    vec3 colors[4];
    float dists[4];
    for (int i = 0; i< COUNT;i++){ // creating circles
         float fi = float(i);
         circs[i] = .2*vec2(cos(2./3.*PI*fi-iTime*.2), sin(2./3.*PI*fi-iTime*.2));

         colors[i] = vec3(sin(fi), cos(fi), .5);
    }
    circs[3]= .4*sin(iTime*1.43)*vec2(cos(2./3.*PI+iTime), sin(2./3.*PI+iTime));
    colors[3]= vec3(uv,.5);

    vec3 col = vec3(0);

    float dist;
    for (int i = 0; i< COUNT;i++) {

         if (XALIGNED) {
              circs[i].x*=RATIO;


         }

         dists[i] = m/length(circs[i] - uv);
         dist += dists[i];
    }
    if (dist > 20.){ // picking the influence of each circle on given pixel if distances sum is more than some arbitrary value
         for (int i = 0; i < COUNT; i++) {
              col += colors[i]*dists[i]/dist;
         }
         //if (fract(iTime*.1) < .5) 
         if (uv.x < -sin(iTime))
         col = vec3((fract(dist) < .1) ? 1. : 0.);
    }
    else {
        col = vec3(.2*uv.y);
        if (uv.x < sin(iTime)) col = vec3(1.0);
    }



    fragColor = vec4(col,1.0);
}
